style.css:
@-moz-document domain("web.whatsapp.com") {
/* --- Efeito de Fundo e Vidro do iOS --- */
    body {
        /* Fundo com degradê suave estilo wallpaper de iPhone */
        background: linear-gradient(135deg, #e2d1c3 0%, #d4dfe6 50%, #b8c6db 100%) !important;
    }

    #app .two {
        background-color: transparent !important;
    }

    /* --- Cabeçalho Superior Translúcido (Glass) --- */
    header {
        background-color: rgba(255, 255, 255, 0.45) !important;
        backdrop-filter: blur(20px) saturate(180%) !important;
        -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
        border-bottom: 1px solid rgba(255, 255, 255, 0.3) !important;
    }

    /* --- Painel Lateral e Conversas --- */
    div[id="side"] {
        background-color: rgba(255, 255, 255, 0.35) !important;
        backdrop-filter: blur(15px) !important;
        -webkit-backdrop-filter: blur(15px) !important;
        border-right: 1px solid rgba(255, 255, 255, 0.2) !important;
    }

    /* --- Área do Chat --- */
    div[data-asset-chat-background="true"] {
        opacity: 0.1 !important; /* Esconde o padrão padrão de fundo */
    }

    /* --- Bolhas de Mensagem Estilo iOS --- */
    /* Mensagens Recebidas (Branco Translúcido) */
    .message-in > div {
        background-color: rgba(255, 255, 255, 0.75) !important;
        backdrop-filter: blur(8px) !important;
        -webkit-backdrop-filter: blur(8px) !important;
        border-radius: 18px 18px 18px 4px !important;
        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05) !important;
        color: #000000 !important;
    }

    /* Mensagens Enviadas (Tom Bege/Pastel Suave estilo a print) */
    .message-out > div {
        background-color: rgba(252, 238, 219, 0.85) !important; /* Amarelo/Creme suave */
        backdrop-filter: blur(8px) !important;
        -webkit-backdrop-filter: blur(8px) !important;
        border-radius: 18px 18px 4px 18px !important;
        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05) !important;
        color: #000000 !important;
    }

    /* --- Barra de Digitação (Rodapé) --- */
    footer {
        background-color: rgba(255, 255, 255, 0.45) !important;
        backdrop-filter: blur(20px) saturate(180%) !important;
        -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
        border-top: 1px solid rgba(255, 255, 255, 0.3) !important;
    }

    /* Campo de texto arredondado estilo iOS */
    footer div[contenteditable="true"] {
        background-color: rgba(255, 255, 255, 0.6) !important;
        border-radius: 20px !important;
        border: 1px solid rgba(200, 200, 200, 0.3) !important;
        padding: 8px 12px !important;
    }

    /* --- Suavização de Fontes --- */
    body, span, div {
        font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", Arial, sans-serif !important;
    }
}
